import{z as i,x as l,o as n,c as d,q as t,j as o,D as A,d as a,s as r,S as s,b as B}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"净值曲线的构造","description":"","frontmatter":{"title":"净值曲线的构造","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/ap-nav-construction.md","filePath":"quant/ap-nav-construction.md","lastUpdated":1791063341000}'),p={name:"quant/ap-nav-construction.md"};function D(c,E,m,u,h,C){const e=l("Mermaid");return n(),d("div",null,[E[2]||(E[2]=t('<h1 id="净值曲线的构造" tabindex="-1">净值曲线的构造 <a class="header-anchor" href="#净值曲线的构造" aria-label="Permalink to &quot;净值曲线的构造&quot;">​</a></h1><div class="epigraph"><p>平滑不是没有波动，是把波动搬进了看不见的估值假设里：报告收益的序列相关越高，离真实的波动越远。</p><footer>—— Getmansky, Lo and Makarov, An Econometric Model of Serial Correlation and Illiquidity in Hedge Fund Returns, Journal of Financial Economics, 2004</footer></div><p><a href="/quant/ap-fee-taxonomy">上一课</a>把毛净差拆成逐层可复算的费用瀑布。扣完之后，数字要落成一条<strong>曲线</strong>：日频、单位化、可重述。缺口在于：净值曲线看起来只是每天记一个数，实际是估值、分红、份额与修订四组决策的叠印；仪器造歪了，之后所有比率、排名与检验都建立在读不准的数上。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>四组决策各有坑。<strong>盯市来源</strong>：交易所收盘价、经纪报价、模型价、最后已知价——同一天可以有不同的「今天的值」；停牌、流动性差的债券与私募持仓让当日市价根本不存在。<strong>分红与拆分</strong>：除息缺口会让曲线在派息日假摔，不处理就制造出只存在于报表里的回撤。<strong>份额化</strong>：申购赎回改变净资产但不应改变单位净值，份额与净资产必须分开记。<strong>错误与修订</strong>：上月发现上月的价错了，曲线改不改、留不留痕。缺口是一条可复算、可重述的净值序列，能通过「数字从哪来、谁改过、依据哪条规则」的审计三问。</p><p><span class="marginnote">数字实例：单位净值 1.20 元的基金每单位派息 0.05 元，除息日净值直接跳到 1.15 元，图上是一根 −4.2% 的大阴线——但持有人账户里多了 0.05 元现金，一分没亏。不把派息还原回曲线，每次派息都会在图上造出一场假回撤。</span></p><h3 id="平滑与失真" tabindex="-1">平滑与失真 <a class="header-anchor" href="#平滑与失真" aria-label="Permalink to &quot;平滑与失真&quot;">​</a></h3><p>用最后已知价或模型价填坑，收益会获得人为的序列相关：观测波动被压缩、与流动资产的表观相关性下降。Getmansky–Lo–Makarov 把平滑写成真实收益与移动平均的卷积，并给出用自相关系数还原真实波动的做法。危害不在描述而在决策：把平滑后的低波动喂进风险平价或风险预算，会给这类策略系统性超配；VaR 与压力测试随之低估左尾。</p><p><span class="marginnote">月末估值是重灾区：持有大量非流动债的组合，月收益的一阶自相关可以显著为正；把观测波动直接当真实波动，同等风险预算下它的「效率」是估值节奏送的，不是策略挣的。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先单位化：单位净值等于净资产除以份额，申购赎回同增减、分母分子同步，单位净值不动——这是第一课时间加权收益的精确载体。分红报两条：显式除息的净值与默认再投的累计净值。估值分级：市场收盘价为一级，可比报价为二级，模型价为三级，每个持仓标注层级，三级占比单列披露。停牌与缺价：用最后已知价加冻结标记，解除时按交易日补记，不跳变。修订政策：错误必须重述并留痕，修正前后两版曲线都归档——回改不留痕比错误本身更伤信任，因为下游所有引用的数都成了孤儿。</p><p><span class="marginnote">常见误区：初学者容易以为大额赎回会砸低单位净值。实际上赎回是按净值拿走属于自己的那份：净资产和份额同比例减少，像从一锅汤里舀走一碗，剩下的汤咸淡不变。会让净值跳变的是估值错误或分红漏记，不是申赎本身。</span></p>',12)),(n(),o(s,null,{default:A(()=>[r(e,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20LEDGER%5B%22%E9%80%90%E7%AC%94%E8%B4%A6%E6%9C%AC%22%5D%20--%3E%20VAL%5B%22%E4%BC%B0%E5%80%BC%E5%88%86%E7%BA%A7%3A%20%E5%B8%82%E4%BB%B7%2F%E6%8A%A5%E4%BB%B7%2F%E6%A8%A1%E5%9E%8B%E4%BB%B7%22%5D%0A%20%20VAL%20--%3E%20FREEZE%5B%22%E7%BC%BA%E4%BB%B7%E4%B8%8E%E5%81%9C%E7%89%8C%3A%20%E6%9C%80%E5%90%8E%E5%B7%B2%E7%9F%A5%E4%BB%B7%E5%8A%A0%E5%86%BB%E7%BB%93%22%5D%0A%20%20FREEZE%20--%3E%20NAV%5B%22%E5%87%80%E8%B5%84%E4%BA%A7%22%5D%0A%20%20NAV%20--%3E%20UNIT%5B%22%E4%BB%BD%E9%A2%9D%E5%8C%96%3A%20%E5%8D%95%E4%BD%8D%E5%87%80%E5%80%BC%22%5D%0A%20%20DIV%5B%22%E5%88%86%E7%BA%A2%E4%B8%8E%E6%8B%86%E5%88%86%22%5D%20--%3E%20UNIT%0A%20%20UNIT%20--%3E%20CURVE%5B%22%E5%87%80%E5%80%BC%E6%9B%B2%E7%BA%BF%22%5D%0A%20%20CURVE%20--%3E%20REST%5B%22%E9%94%99%E8%AF%AF%E9%87%8D%E8%BF%B0%3A%20%E5%89%8D%E5%90%8E%E4%B8%A4%E7%89%88%E5%BD%92%E6%A1%A3%22%5D%0A%20%20REST%20--%3E%20AUDIT%5B%22%E5%AE%A1%E8%AE%A1%E4%B8%89%E9%97%AE%E5%8F%AF%E7%AD%94%22%5D%0A"})]),fallback:A(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B("h2",{id:"机制",tabindex:"-1"},[a("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=B("p",null,[a("净值曲线是后续一切评价的"),B("strong",null,"测量仪器"),a("：仪器失真，读数无意义。份额化把账户变成证券，使时间加权收益有了可复算的对象——单位净值的链式增长就是 TWR，申赎不再进入分子分母。平滑的机制值得记住：它等价于把真实收益与一个低通滤波卷积，二阶矩被压缩，压缩量可以从自相关结构里估出来；这也意味着"),B("strong",null,"平滑污染持续性检验"),a("——月频平滑的排序看起来更稳，「技能」的可信度被估值节奏抬高，评估单元要用还原后的收益重算。")],-1)),(n(),o(s,null,{default:A(()=>[r(e,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20ILL%5B%22%E9%9D%9E%E6%B5%81%E5%8A%A8%E6%8C%81%E4%BB%93%3A%20%E5%BD%93%E6%97%A5%E6%97%A0%E7%9C%9F%E5%AE%9E%E5%B8%82%E4%BB%B7%22%5D%20--%3E%20FILL%5B%22%E7%94%A8%E6%9C%80%E5%90%8E%E5%B7%B2%E7%9F%A5%E4%BB%B7%E6%88%96%E6%A8%A1%E5%9E%8B%E4%BB%B7%E5%A1%AB%E5%9D%91%22%5D%0A%20%20FILL%20--%3E%20AVG%5B%22%E7%9B%B8%E9%82%BB%E4%B8%A4%E6%9C%9F%E6%94%B6%E7%9B%8A%E8%A2%AB%E6%91%8A%E5%B9%B3%22%5D%0A%20%20AVG%20--%3E%20AC%5B%22%E6%94%B6%E7%9B%8A%E5%87%BA%E7%8E%B0%E4%BA%BA%E4%B8%BA%E6%AD%A3%E8%87%AA%E7%9B%B8%E5%85%B3%22%5D%0A%20%20AC%20--%3E%20LOWV%5B%22%E8%A7%82%E6%B5%8B%E6%B3%A2%E5%8A%A8%E4%BD%8E%E4%BA%8E%E7%9C%9F%E5%AE%9E%E6%B3%A2%E5%8A%A8%22%5D%0A%20%20LOWV%20--%3E%20ALLOC%5B%22%E9%A3%8E%E9%99%A9%E9%A2%84%E7%AE%97%E6%8D%AE%E6%AD%A4%E8%B6%85%E9%85%8D%E8%AF%A5%E7%AD%96%E7%95%A5%22%5D%0A%20%20AC%20--%3E%20PERS%5B%22%E6%8C%81%E7%BB%AD%E6%80%A7%E6%A3%80%E9%AA%8C%E4%B9%9F%E8%A2%AB%E5%B9%B3%E6%BB%91%E6%8A%AC%E9%AB%98%22%5D%0A"})]),fallback:A(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=t('<p><span class="marginnote">直觉类比：平滑像把颠簸的山路画成一条平缓的曲线——地图看着好走，坑一个没少。用平滑后的波动做风险预算，等于照着美化过的地图配装备，真正的陡坡（左尾）出现时才发现头盔带少了。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不回答曲线好不好——那是评估单元的比率与基准的事。估值分歧的仲裁层级与 IPV，做市课程已给出口径，此处不重复。曲线的抽样误差与统计检验不属于核算单元。平滑对持续性测量的具体污染方式，放到本课程<a href="/quant/ap-performance-persistence">绩效的持续性</a>再算。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>净值曲线是估值、分红、份额、修订四组决策的叠印，不是每天记一个数。</li><li>估值要分级标注，缺价用最后已知价加冻结，解除后按交易日补记。</li><li>平滑把波动搬进估值假设：观测波动低估、相关性失真，可按自相关还原。</li><li>错误必须重述并留痕，修正前后两版都归档；回改不留痕比错误更伤。</li><li>出处：Getmansky, Lo and Makarov, <em>Journal of Financial Economics</em>, 2004；份额化与再投口径据 GIPS 惯例整理。</li></ul>',5))])}const g=i(p,[["render",D]]);export{_ as __pageData,g as default};
